package com.example.practice;

import org.jpos.core.Configuration;
import org.jpos.core.ConfigurationException;
import org.jpos.q2.QBeanSupport;
import org.jpos.util.NameRegistrar;

/**
 * While an issuer can't be reached, the switch approves small purchases in stand-in, up to the
 * limit this QBean holds. Deployed from a descriptor such as:
 *
 * <pre>
 * &lt;standin name="standin" class="com.example.practice.StandInLimit"&gt;
 *   &lt;property name="max-amount" value="${STANDIN_MAX}"/&gt;
 *   &lt;property name="currency" value="${STANDIN_CURRENCY}"/&gt;
 * &lt;/standin&gt;
 * </pre>
 */
public class StandInLimit extends QBeanSupport {
    private long maxAmount;                       // minor units: 5000 is 50.00
    private String currency;                      // ISO 4217 numeric code, such as 840 or 978

    @Override
    public void setConfiguration(Configuration cfg) throws ConfigurationException {
        super.setConfiguration(cfg);
        read(cfg);
    }

    /** Takes this descriptor's values into the fields above. */
    void read(Configuration cfg) throws ConfigurationException {
        String max = cfg.get("max-amount", null);
        if (max == null)
            throw new ConfigurationException("property 'max-amount' is required");
        try {
            maxAmount = Long.parseLong(max.trim());
        } catch (NumberFormatException e) {
            throw new ConfigurationException("property 'max-amount' is not a number: " + max, e);
        }
        currency = cfg.get("currency", "840");
    }

    @Override
    protected void startService() {
        NameRegistrar.register(getName(), this);
    }

    @Override
    protected void stopService() {
        NameRegistrar.unregister(getName());
    }

    /** True when a purchase of this amount, in this currency, may be approved in stand-in. */
    public boolean allows(String currency, long amount) {
        return this.currency.equals(currency) && amount > 0 && amount <= maxAmount;
    }
}

import com.example.practice.StandInLimit;
import org.jpos.core.ConfigurationException;
import org.jpos.core.SimpleConfiguration;

import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) throws Exception {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        Logger root = Logger.getLogger("");
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            StandInLimit gbp = deploy("4000", "826");
            System.out.println("826 limit 4000, 40.00 GBP allowed: " + (gbp != null && gbp.allows("826", 4000)));
            System.out.println("826 limit 4000, 40.01 GBP allowed: " + (gbp != null && gbp.allows("826", 4001)));
            StandInLimit usd = deploy("1500", "${STANDIN_CURRENCY}");
            System.out.println("currency unset, 15.00 USD allowed: " + (usd != null && usd.allows("840", 1500)));
            deploy("${STANDIN_MAX}", "826");
            deploy("40.00", "826");
            deploy(" 4000x", "826");
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }

    /** What Q2 does with the descriptor's properties; null when the QBean refuses them. */
    private static StandInLimit deploy(String maxAmount, String currency) {
        SimpleConfiguration cfg = new SimpleConfiguration();
        cfg.put("max-amount", maxAmount);
        cfg.put("currency", currency);
        StandInLimit limit = new StandInLimit();
        try {
            limit.setConfiguration(cfg);
            System.out.println("max-amount '" + maxAmount + "': accepted");
            return limit;
        } catch (ConfigurationException e) {
            System.out.println("max-amount '" + maxAmount + "': refused, " + e.getMessage());
            return null;
        }
    }
}

